export function parseRange(s: string): [number, number] {
  const parts = s.split("-");
  const a = Number(parts[0]);
  const b = Number(parts[1]);
  if (Number.isNaN(a) || Number.isNaN(b)) {
    throw new Error("bad range");
  }
  return [a, b];
}

